{
  "units": [
    {
      "quote": "A valid authorization is a document that meets the requirements in paragraphs (a)(3)(ii), (a)(4)(ii), (c)(1), and (c)(2) of this section, as applicable.",
      "scope_quotes": [
        "(b) Implementation specifications: General requirements—(1) Valid authorizations."
      ],
      "kind": "definition",
      "meaning": "Under general implementation specifications, a valid authorization is defined as a document that satisfies the applicable requirements set forth in paragraphs (a)(3)(ii), (a)(4)(ii), (c)(1), and (c)(2) of this section."
    },
    {
      "quote": "A valid authorization may contain elements or information in addition to the elements required by this section, provided that such additional elements or information are not inconsistent with the elements required by this section.",
      "scope_quotes": [
        "(b) Implementation specifications: General requirements—(1) Valid authorizations."
      ],
      "kind": "permission",
      "meaning": "A valid authorization is permitted to include elements or information beyond what is required by this section, conditioned upon those additional elements or information not being inconsistent with the required elements."
    },
    {
      "quote": "An authorization is not valid, if the document submitted has any of the following defects:",
      "scope_quotes": [
        "(2) Defective authorizations."
      ],
      "kind": "condition",
      "meaning": "An authorization document is rendered invalid if it contains any one or more of the defects specified in paragraphs (b)(2)(i) through (v)."
    },
    {
      "quote": "The expiration date has passed or the expiration event is known by the covered entity to have occurred;",
      "scope_quotes": [
        "(2) Defective authorizations. An authorization is not valid, if the document submitted has any of the following defects:"
      ],
      "kind": "condition",
      "meaning": "An authorization is invalid if its expiration date has elapsed, or if the covered entity has knowledge that the specified expiration event has occurred."
    },
    {
      "quote": "The authorization has not been filled out completely, with respect to an element described by paragraph (c) of this section, if applicable;",
      "scope_quotes": [
        "(2) Defective authorizations. An authorization is not valid, if the document submitted has any of the following defects:"
      ],
      "kind": "condition",
      "meaning": "An authorization is invalid if it has not been filled out completely regarding any applicable element described in paragraph (c) of this section."
    },
    {
      "quote": "The authorization is known by the covered entity to have been revoked;",
      "scope_quotes": [
        "(2) Defective authorizations. An authorization is not valid, if the document submitted has any of the following defects:"
      ],
      "kind": "condition",
      "meaning": "An authorization is invalid if the covered entity has knowledge that the authorization has been revoked."
    },
    {
      "quote": "The authorization violates paragraph (b)(3) or (4) of this section, if applicable;",
      "scope_quotes": [
        "(2) Defective authorizations. An authorization is not valid, if the document submitted has any of the following defects:"
      ],
      "kind": "condition",
      "meaning": "An authorization is invalid if it violates paragraph (b)(3) or paragraph (b)(4) of this section, where applicable."
    },
    {
      "quote": "Any material information in the authorization is known by the covered entity to be false.",
      "scope_quotes": [
        "(2) Defective authorizations. An authorization is not valid, if the document submitted has any of the following defects:"
      ],
      "kind": "condition",
      "meaning": "An authorization is invalid if any material information contained within it is known by the covered entity to be false."
    }
  ]
}
